    iterator.insert("M");
    assertEquals(list, new LinkedList<String>("M", "G", "B", "F", "D"));
    assertEquals(iterator.next(), "M");
    iterator.insert("N");
    assertEquals(list, new LinkedList<String>("M", "N", "G", "B", "F", "D"));
    iterator = list.iterator();
    iterator.toEnd();
    assertEquals(iterator.previous(), "D");
    iterator.toStart();
    assertEquals(iterator.next(), "M");
}

