@Test
public void testCRUD() throws IOException, SerializationException, QueryException {
    JSONSerializer jsonSerializer = new JSONSerializer();
    Object contact = jsonSerializer.readObject(getClass().getResourceAsStream("contact.json"));
    // Create
    PostQuery postQuery = new PostQuery(hostname, port, "/pivot-demos/rest_demo", secure);
    postQuery.setValue(contact);
    URL location = postQuery.execute();
    assertNotNull(location);
    String path = location.getPath();
    // Read
    GetQuery getQuery = new GetQuery(hostname, port, path, secure);
    assertEquals(contact, getQuery.execute());
    // Update
    JSON.put(contact, "name", "Joseph User");
    PutQuery putQuery = new PutQuery(hostname, port, path, secure);
    putQuery.setValue(contact);
    boolean created = putQuery.execute();
    assertFalse(created);
    assertEquals(contact, getQuery.execute());
    // Delete
    DeleteQuery deleteQuery = new DeleteQuery(hostname, port, path, secure);
    deleteQuery.execute();
    assertEquals(deleteQuery.getStatus(), Query.Status.NO_CONTENT);
}

@Test(expected = IndexOutOfBoundsException.class)
public void testQueryDictionary() {
    QueryDictionary dict = new QueryDictionary(true);
    assertNull(dict.get("key"));
    dict.put("key", "value");
    assertNotNull(dict.get("key"));
    assertEquals("value", dict.get("key", 0));
    assertEquals(1, dict.getLength("key"));
    dict.get("key", 1);
    assertEquals("value", dict.put("key", "value2"));
    assertEquals("value2", dict.get("key"));
    dict.add("key", "another value");
    assertEquals("another value", dict.get("key", 1));
    assertEquals(0, dict.getLength("nokey"));
    assertEquals(0, dict.add("key2", "new value"));
    dict.insert("key", "yet another value", 0);
    assertEquals(3, dict.getLength("key"));
    dict.insert("key", "bad value", 10);
    assertEquals("yet another value", dict.remove("key"));
    assertNull(dict.remove("key"));
    dict.add("key2", "2nd value");
    assertEquals("new value", dict.remove("key2", 0));
    dict.remove("key2", 10);
    dict.add("key3", "something");
    Set<String> validKeys = new HashSet<String>();
    validKeys.add("key2");
    validKeys.add("key3");
    for (String s : dict) {
        assertTrue(s, validKeys.remove(s));
    }
    assertEquals(0, validKeys.size());
    assertTrue(dict.containsKey("key2"));
    dict.clear();
}
